var PRODUCTS_VERSION = 3;
var pendingImgData = null, pendingImgRemoved = false;

// ===== DATABASE LOCAL STORAGE SUPER AMAN =====
function loadProducts() {
    var data = localStorage.getItem(LS_PRODUCTS);
    var savedVer = localStorage.getItem(LS_PRODUCTS_VER);
    var isValid = false;
    
    if (data && savedVer === String(PRODUCTS_VERSION)) { 
        try { 
            var parsed = JSON.parse(data);
            if (Array.isArray(parsed) && parsed.length > 0 && parsed[0] && parsed[0].nm && parsed[0].cat) {
                P = parsed;
                isValid = true;
            }
        } catch(e) { } 
    }
    
    if (!isValid) {
        P = JSON.parse(JSON.stringify(defaultP));
        localStorage.removeItem(LS_PRODUCTS);
        localStorage.setItem(LS_PRODUCTS_VER, String(PRODUCTS_VERSION));
    }
    
    for (var i = 0; i < P.length; i++) { 
        if (!P[i].nm) P[i].nm = {id: 'Produk', en: 'Product'};
        if (!P[i].cat) P[i].cat = 'amigurumi';
        if (!P[i].ds) P[i].ds = {id: '', en: ''};
        
        P[i].img = P[i].customImg ? P[i].customImg : mkSVG(P[i].cat, P[i].nm.id); 
    }
}

function saveProducts() { 
    var cleanP = P.map(function(p) {
        var out = { id: p.id, nm: p.nm, cat: p.cat, pr: p.pr, ds: p.ds, rt: p.rt, st: p.st };
        if (p.customImg) out.customImg = p.customImg;
        return out;
    });
    try {
        localStorage.setItem(LS_PRODUCTS, JSON.stringify(cleanP)); 
        localStorage.setItem(LS_PRODUCTS_VER, String(PRODUCTS_VERSION));
    } catch (e) {
        toast('Penyimpanan penuh! Coba hapus foto produk lain atau gunakan foto lebih kecil.', 'e');
    }
}

function loadOrders() { 
    var data = localStorage.getItem(LS_ORDERS); 
    if (data) { 
        try { orders = JSON.parse(data); } 
        catch(e) { orders = []; } 
    } else { orders = []; } 
}
function saveOrders() { localStorage.setItem(LS_ORDERS, JSON.stringify(orders)); }

