function copyVA(el) { var text = el.innerText; if (navigator.clipboard) { navigator.clipboard.writeText(text).then(function() { showCopied(el); }); } else { var ta = document.createElement("textarea"); ta.value = text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); showCopied(el); } }
