function loadProfile() { var data = localStorage.getItem(LS_PROFILE); if (!data) return false; try { var p = JSON.parse(data); if (p.name) document.getElementById('chN').value = p.name; if (p.phone) document.getElementById('chP').value = p.phone; if (p.email) document.getElementById('chE').value = p.email; if (p.address) document.getElementById('chA').value = p.address; if (p.city) document.getElementById('chC').value = p.city; if (p.zip) document.getElementById('chZ').value = p.zip; return true; } catch (e) { return false; } }
