function renderProducts() { var grid = document.getElementById('pGrid'), noRes = document.getElementById('noRes'); var filtered = P.filter(function(p) { if (filt.cat !== 'all' && p.cat !== filt.cat) return false; if (filt.q && gn(p).toLowerCase().indexOf(filt.q.toLowerCase()) === -1) return false; if (filt.price !== 'all') { if (filt.price === 'u50' && p.pr >= 50000) return false; if (filt.price === '50100' && (p.pr < 50000 || p.pr > 100000)) return false; if (filt.price === '100200' && (p.pr < 100000 || p.pr > 200000)) return false; if (filt.price === 'o200' && p.pr <= 200000) return false; } return true; }); if (filt.sort === 'name') filtered.sort(function(a, b) { return gn(a).localeCompare(gn(b)); }); if (filt.sort === 'pl') filtered.sort(function(a, b) { return a.pr - b.pr; }); if (filt.sort === 'ph') filtered.sort(function(a, b) { return b.pr - a.pr; }); if (filt.sort === 'rat') filtered.sort(function(a, b) { return b.rt - a.rt; }); if (filtered.length === 0) { grid.innerHTML = ''; noRes.style.display = 'block'; return; } noRes.style.display = 'none'; var html = ''; for (var i = 0; i < filtered.length; i++) { var p = filtered[i], oos = p.st <= 0; html += '<div class="product-card" style="animation-delay:' + (i * 0.05) + 's"><div class="product-img-wrap"><img src="' + p.img + '" alt="' + gn(p) + '" loading="lazy"><span class="product-badge ' + bcls(p.cat) + '">' + p.cat + '</span><div class="product-overlay"><button class="btn btn-primary btn-sm" onclick="openPM(' + p.id + ')">' + t('btn_det') + '</button>' + (!oos ? '<button class="btn btn-outline btn-sm" onclick="addCart(' + p.id + ')">' + t('btn_add') + '</button>' : '') + '</div></div><div class="product-info"><div class="product-name">' + gn(p) + '</div><div class="product-rating">' + stars(p.rt) + '</div><div class="product-bottom"><span class="product-price">' + fp(p.pr) + '</span>' + (!oos ? '<button class="btn-add-cart" onclick="addCart(' + p.id + ')"><i class="fas fa-plus"></i></button>' : '') + '</div><div class="product-stock ' + (oos ? 'out' : '') + '">' + (oos ? t('oos') : p.st + ' ' + t('stk')) + '</div></div></div>'; } grid.innerHTML = html; }
function filterCat(cat) { filt.cat = cat; var btns = document.querySelectorAll('.cat-btn'); for (var i = 0; i < btns.length; i++) btns[i].classList.toggle('active', btns[i].getAttribute('data-c') === cat); renderProducts(); }

