function addCart(id, qty) { qty = qty || 1; var p = P.find(function(x) { return x.id === id; }); if (!p || p.st <= 0) { toast(t('oos'), 'e'); return; } var item = cart.find(function(x) { return x.id === id; }); if (item) { var nq = item.qty + qty; if (nq > p.st) { toast(t('oos'), 'e'); return; } item.qty = nq; } else { cart.push({id: id, qty: qty}); } toast(t('t_add')); renderCart(); }
function updCartQty(id, d) { var item = cart.find(function(x) { return x.id === id; }), p = P.find(function(x) { return x.id === id; }); if (!item || !p) return; item.qty += d; if (item.qty <= 0) { cart = cart.filter(function(x) { return x.id !== id; }); toast(t('t_rem')); } else if (item.qty > p.st) { item.qty = p.st; toast(t('oos'), 'e'); } else { toast(t('t_upd')); } renderCart(); }
function rmCart(id) { cart = cart.filter(function(x) { return x.id !== id; }); toast(t('t_rem')); renderCart(); }
function cartTotal() { var t = 0; for (var i = 0; i < cart.length; i++) { var p = P.find(function(x) { return x.id === cart[i].id; }); if (p) t += p.pr * cart[i].qty; } return t; }
function cartCount() { var c = 0; for (var i = 0; i < cart.length; i++) c += cart[i].qty; return c; }
function renderCart() { var body = document.getElementById('cBody'), foot = document.getElementById('cFoot'), badge = document.getElementById('cBadge'), count = cartCount(); if (count > 0) { badge.style.display = 'flex'; badge.textContent = count; } else { badge.style.display = 'none'; } if (cart.length === 0) { body.innerHTML = '<div class="cart-empty"><div class="cart-empty-icon">🛒</div><p>' + t('c_empty') + '</p></div>'; foot.style.display = 'none'; return; } foot.style.display = 'block'; document.getElementById('cTotal').textContent = fp(cartTotal()); var html = ''; for (var i = 0; i < cart.length; i++) { var item = cart[i], p = P.find(function(x) { return x.id === item.id; }); if (!p) continue; html += '<div class="cart-item"><img class="cart-item-img" src="' + p.img + '" alt=""><div class="cart-item-info"><div class="cart-item-name">' + gn(p) + '</div><div class="cart-item-price">' + fp(p.pr * item.qty) + '</div><div class="cart-item-actions"><button class="cart-qty-btn" onclick="updCartQty(' + p.id + ',-1)">−</button><span class="cart-item-qty">' + item.qty + '</span><button class="cart-qty-btn" onclick="updCartQty(' + p.id + ',1)">+</button><span class="cart-item-remove" onclick="rmCart(' + p.id + ')"><i class="fas fa-trash"></i></span></div></div></div>'; } body.innerHTML = html; }
function toggleCart() { document.getElementById('cOver').classList.toggle('show'); document.getElementById('cSide').classList.toggle('open'); renderCart(); }

// ===== MODAL PRODUK =====
function openPM(id) { var p = P.find(function(x) { return x.id === id; }); if (!p) return; mQty = 1; var oos = p.st <= 0; var html = '<div class="modal-product-img"><img src="' + p.img + '" alt="' + gn(p) + '"></div><div class="modal-product-details"><h2>' + gn(p) + '</h2><div class="product-rating">' + stars(p.rt) + '</div><div class="product-price">' + fp(p.pr) + '</div><p class="description">' + gd(p) + '</p>'; if (!oos) { html += '<div class="qty-selector"><label>Qty:</label><div class="qty-controls"><button onclick="chgMQty(-1)">−</button><span id="mQtyVal">1</span><button onclick="chgMQty(1)">+</button></div></div><div class="modal-actions"><button class="btn btn-primary" onclick="addCart(' + p.id + ',mQty);closePM()">' + t('btn_add') + '</button><button class="btn btn-outline" onclick="addCart(' + p.id + ',mQty);closePM();goCheck()">' + t('btn_buy') + '</button></div>'; } else { html += '<p style="color:#e74c3c;font-weight:700">' + t('oos') + '</p>'; } html += '</div>'; document.getElementById('pmBody').innerHTML = html; document.getElementById('pModal').classList.add('show'); }
function chgMQty(d) { mQty = Math.max(1, mQty + d); var el = document.getElementById('mQtyVal'); if (el) el.textContent = mQty; }
function closePM() { document.getElementById('pModal').classList.remove('show'); }

// ===== CHECKOUT =====
function goCheck() { if (cart.length === 0) { toast(t('e_empty'), 'e'); return; } toggleCart(); document.getElementById('chkPage').style.display = 'block'; document.body.style.overflow = 'hidden'; var hasData = loadProfile(); var titleEl = document.getElementById('chkTitle'); var oldInd = titleEl.querySelector('.saved-indicator'); if (oldInd) oldInd.remove(); if (hasData) { var ind = document.createElement('span'); ind.className = 'saved-indicator'; ind.innerHTML = '<i class="fas fa-check-circle"></i> Data tersimpan'; titleEl.appendChild(ind); } renderChkItems(); updTot(); }
function closeChk() { document.getElementById('chkPage').style.display = 'none'; document.body.style.overflow = ''; clearErrors(); }
function renderChkItems() { var html = ''; for (var i = 0; i < cart.length; i++) { var item = cart[i], p = P.find(function(x) { return x.id === item.id; }); if (!p) continue; html += '<div class="checkout-item"><img class="checkout-item-img" src="' + p.img + '" alt=""><div class="checkout-item-info"><div class="checkout-item-name">' + gn(p) + '</div><div class="checkout-item-qty">x' + item.qty + '</div></div><div class="checkout-item-price">' + fp(p.pr * item.qty) + '</div></div>'; } document.getElementById('chkItems').innerHTML = html; }
function getShipCost() { var s = document.querySelector('input[name="ship"]:checked'); if (!s) return 0; return {reg:15000, exp:25000, sday:40000}[s.value] || 0; }
function updTot() { var sub = cartTotal(), ship = getShipCost(); document.getElementById('chSub').textContent = fp(sub); document.getElementById('chShip').textContent = fp(ship); document.getElementById('chGrand').textContent = fp(sub + ship); }
function clearErrors() { var errs = document.querySelectorAll('.form-error'); for (var i = 0; i < errs.length; i++) errs[i].textContent = ''; }
function validateForm() { clearErrors(); var valid = true; var name = document.getElementById('chN').value.trim(), phone = document.getElementById('chP').value.trim(), email = document.getElementById('chE').value.trim(), addr = document.getElementById('chA').value.trim(), city = document.getElementById('chC').value.trim(), zip = document.getElementById('chZ').value.trim(); if (!name) { document.getElementById('eN').textContent = t('e_req'); valid = false; } if (!phone || !/^[0-9+\-\s]{8,15}$/.test(phone)) { document.getElementById('eP').textContent = t('e_phone'); valid = false; } if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { document.getElementById('eE').textContent = t('e_mail'); valid = false; } if (!addr) { document.getElementById('eA').textContent = t('e_req'); valid = false; } if (!city) { document.getElementById('eC').textContent = t('e_req'); valid = false; } if (!zip || !/^[0-9]{5}$/.test(zip)) { document.getElementById('eZ').textContent = t('e_post'); valid = false; } return valid; }

function doPay() {
    if (!validateForm()) return;
    var payMethod = document.querySelector('input[name="pay"]:checked'); if (!payMethod) return;
    var sub = cartTotal(), ship = getShipCost(), total = sub + ship, orderId = 'PYC' + Date.now().toString().slice(-8);
    var payValue = payMethod.value;
    var bankKey = null, bankInfo = null;
    if (payValue === 'bank') { bankKey = document.getElementById('bankChoice').value; bankInfo = BANK_INFO[bankKey]; }
    var order = { id: orderId, name: document.getElementById('chN').value.trim(), email: document.getElementById('chE').value.trim(), phone: document.getElementById('chP').value.trim(), address: document.getElementById('chA').value.trim(), city: document.getElementById('chC').value.trim(), zip: document.getElementById('chZ').value.trim(), items: JSON.parse(JSON.stringify(cart)), subtotal: sub, shipping: ship, total: total, payMethod: payValue, bankLabel: bankInfo ? bankInfo.name : null, status: 'pending', date: new Date().toISOString() };
    orders.push(order);

    // Kurangi stok produk sesuai barang yang dipesan
    for (var i = 0; i < cart.length; i++) {
        var p = P.find(function(x) { return x.id === cart[i].id; });
        if (p) p.st = Math.max(0, p.st - cart[i].qty);
    }

    saveOrders(); saveProducts();
    
    document.getElementById('sucMsg').textContent = t('pay_ok_msg');
    var payLabel = payValue === 'qris' ? 'QRIS' : payValue === 'bank' ? ('Transfer ' + bankInfo.name) : 'COD (Bayar di Tempat)';
    var detHtml = '<p>Order ID: <strong>' + orderId + '</strong></p>' + (payValue !== 'cod' ? ('<p>' + t('pay_before') + ': <strong id="payDeadline">' + new Date(Date.now() + 24*60*60*1000).toLocaleString('id-ID') + '</strong></p>') : '') + '<p>Total: <strong>' + fp(total) + '</strong></p><p>Metode: <strong>' + payLabel + '</strong></p>';
    
    if (payValue === 'qris') {
        detHtml += '<div class="qris-card"><img src="' + mkQRIS(total) + '" alt="QRIS Payment"></div>';
        detHtml += '<p style="font-size:.85rem;color:var(--brown-light);text-align:center;margin-bottom:8px">' + t('qr_scan_qris') + '</p>';
        detHtml += '<div id="qrisTimerHtml" style="text-align:center;font-size:.85rem;color:var(--yellow);font-weight:600;margin-bottom:16px">⏱ <span id="qrisCountdown">23:59:59</span></div>';
        startQrisTimer();
    } else if (payValue === 'bank') {
        var va = generateVA(bankInfo.code);
        detHtml += '<div class="va-box" style="border-color:' + bankInfo.color + '"><div style="font-size:3rem;margin-bottom:10px">🏦</div><div style="font-size:1rem;font-weight:700;color:' + bankInfo.color + ';margin-bottom:4px">Virtual Account ' + bankInfo.name + '</div><div style="font-size:1.5rem;font-weight:700;color:var(--pink-dark);margin-bottom:12px">' + fp(total) + '</div><p style="font-size:.9rem;color:var(--brown);margin-bottom:12px"><i class="fas fa-info-circle"></i> ' + bankInfo.howto + '</p><div class="va-number" style="background:' + bankInfo.color + '" onclick="copyVA(this)">' + va + '</div><p class="va-hint">Klik untuk menyalin</p></div>';
    } else if (payValue === 'cod') {
        detHtml += '<div class="va-box" style="border-color:var(--mint)"><div style="font-size:3rem;margin-bottom:10px">💵</div><div style="font-size:1rem;font-weight:700;color:#2d7a5f;margin-bottom:4px">Cash on Delivery</div><div style="font-size:1.5rem;font-weight:700;color:var(--pink-dark);margin-bottom:12px">' + fp(total) + '</div><p style="font-size:.9rem;color:var(--brown);margin-bottom:0"><i class="fas fa-info-circle"></i> Siapkan uang tunai pas sejumlah di atas. Bayar langsung ke kurir saat paket sampai di alamatmu.</p></div>';
    }
    
    document.getElementById('sucDet').innerHTML = detHtml;
    document.getElementById('sucModal').classList.add('show');
    saveProfile(); cart = []; renderCart(); renderProducts(); closeChk();
}

function startQrisTimer() { if (qrisTimer) clearInterval(qrisTimer); var endTime = Date.now() + 24 * 60 * 60 * 1000; qrisTimer = setInterval(function() { var diff = endTime - Date.now(); if (diff <= 0) { clearInterval(qrisTimer); var el = document.getElementById('qrisCountdown'); if (el) el.textContent = 'Expired'; return; } var h = Math.floor(diff / 3600000), m = Math.floor((diff % 3600000) / 60000), s = Math.floor((diff % 60000) / 1000); var el = document.getElementById('qrisCountdown'); if (el) el.textContent = String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0'); }, 1000); }
function closeSuc() { document.getElementById('sucModal').classList.remove('show'); if (qrisTimer) { clearInterval(qrisTimer); qrisTimer = null; } }

