function closeLog() { document.getElementById('logModal').classList.remove('show'); }
function doLog() { var u = document.getElementById('logU').value, p = document.getElementById('logP').value; if (u === 'admin' && p === 'admin123') { isAdmin = true; document.getElementById('adminNav').style.display = 'inline-flex'; closeLog(); toast('Login berhasil!', 's'); setTimeout(function() { openAdm(); }, 300); } else { document.getElementById('logErr').textContent = 'Username atau password salah'; } }
