function resetAllData() {
    if (!confirm('PERINGATAN: Ini akan menghapus SEMUA data pesanan, produk yang ditambahkan, dan stok yang sudah berubah. Yakin ingin melanjutkan?')) return;
    localStorage.removeItem(LS_PRODUCTS);
    localStorage.removeItem(LS_PRODUCTS_VER);
    localStorage.removeItem(LS_ORDERS);
    localStorage.removeItem(LS_PROFILE);
    location.reload();
}

function renderAdm() {
    var totalProducts = P.length, totalStock = 0, totalValue = 0;
    for (var i = 0; i < P.length; i++) { totalStock += P[i].st; totalValue += P[i].pr * P[i].st; }
    var totalOrders = orders.length, totalRevenue = 0; for (var i = 0; i < orders.length; i++) totalRevenue += orders[i].total;
    document.getElementById('admStats').innerHTML = '<div class="admin-stat-card"><div class="sn">' + totalProducts + '</div><div class="sl">Produk</div></div><div class="admin-stat-card"><div class="sn">' + totalStock + '</div><div class="sl">Total Stok</div></div><div class="admin-stat-card"><div class="sn">' + fp(totalValue) + '</div><div class="sl">Nilai Stok</div></div><div class="admin-stat-card"><div class="sn">' + totalOrders + '</div><div class="sl">Pesanan</div></div><div class="admin-stat-card"><div class="sn">' + fp(totalRevenue) + '</div><div class="sl">Pendapatan</div></div>';
    var tbHtml = ''; for (var i = 0; i < P.length; i++) { var p = P[i]; tbHtml += '<tr><td>' + p.id + '</td><td><div class="pc"><img src="' + p.img + '" alt="">' + gn(p) + '</div></td><td>' + p.cat + '</td><td>' + fp(p.pr) + '</td><td>' + p.st + '</td><td><button class="ab ab-e" onclick="editPF(' + p.id + ')"><i class="fas fa-edit"></i></button><button class="ab ab-d" onclick="delPF(' + p.id + ')"><i class="fas fa-trash"></i></button></td></tr>'; }
    document.getElementById('admTB').innerHTML = tbHtml;
    var ordHtml = '', noOrd = document.getElementById('noOrd');
    if (orders.length === 0) { noOrd.style.display = 'block'; } else { noOrd.style.display = 'none'; for (var i = orders.length - 1; i >= 0; i--) { var o = orders[i]; ordHtml += '<tr><td>' + o.id + '</td><td>' + o.name + '</td><td>' + fp(o.total) + '</td><td>' + payMethodLabel(o) + '</td><td>' + ordStatusSelect(o) + '</td><td><button class="ab ab-e" onclick="openOrd(\'' + o.id + '\')"><i class="fas fa-eye"></i> Detail</button></td></tr>'; } }
    document.getElementById('ordTB').innerHTML = ordHtml;
}

// ===== STATUS PESANAN =====
var ORDER_STATUSES = ['pending', 'processing', 'shipped', 'completed', 'cancelled'];
function statusLabel(s) { return {pending:'Menunggu Pembayaran', processing:'Sedang Diproses', shipped:'Sedang Dikirim', completed:'Selesai', cancelled:'Dibatalkan'}[s] || s; }
function payMethodLabel(o) {
    if (o.payMethod === 'qris') return 'QRIS';
    if (o.payMethod === 'bank') return 'Transfer ' + (o.bankLabel || 'Bank');
    if (o.payMethod === 'cod') return 'COD (Bayar di Tempat)';
    if (o.payMethod === 'gopay') return 'GoPay';
    if (o.payMethod === 'bca') return 'Transfer Bank BCA';
    if (o.payMethod === 'mandiri') return 'Transfer Bank Mandiri';
    if (o.payMethod === 'cc') return 'Kartu Kredit/Debit';
    return (o.payMethod || '').toUpperCase();
}
function ordStatusSelect(o) {
    var opts = '';
    for (var i = 0; i < ORDER_STATUSES.length; i++) { var s = ORDER_STATUSES[i]; opts += '<option value="' + s + '"' + (o.status === s ? ' selected' : '') + '>' + statusLabel(s) + '</option>'; }
    return '<select class="status-select st-' + o.status + '" onchange="updOrdStatus(\'' + o.id + '\', this.value)">' + opts + '</select>';
}
function updOrdStatus(id, newStatus) {
    var o = orders.find(function(x) { return x.id === id; });
    if (!o) return;
    o.status = newStatus;
    saveOrders();
    toast('Status pesanan ' + id + ' diubah ke: ' + statusLabel(newStatus));
    renderAdm();
    var modal = document.getElementById('ordModal');
    if (modal && modal.classList.contains('show')) openOrd(id);
}
function openOrd(id) {
    var o = orders.find(function(x) { return x.id === id; });
    if (!o) return;
    var itemsHtml = '';
    for (var i = 0; i < o.items.length; i++) {
        var it = o.items[i], p = P.find(function(x) { return x.id === it.id; });
        var nama = p ? gn(p) : 'Produk #' + it.id;
        var harga = p ? p.pr : 0;
        itemsHtml += '<div class="ord-item-row"><span>' + nama + ' <span style="color:var(--brown-muted)">x' + it.qty + '</span></span><span>' + fp(harga * it.qty) + '</span></div>';
    }
    var html = '';
    html += '<div class="ord-detail-section"><h4>Info Pesanan</h4><div class="ord-detail-row"><strong>Order ID:</strong> ' + o.id + '</div><div class="ord-detail-row"><strong>Tanggal:</strong> ' + new Date(o.date).toLocaleString('id-ID') + '</div><div class="ord-detail-row"><strong>Status:</strong> ' + ordStatusSelect(o) + '</div></div>';
    html += '<div class="ord-detail-section"><h4>Barang Dipesan</h4>' + itemsHtml + '</div>';
    html += '<div class="ord-detail-section"><h4>Ringkasan</h4><div class="ord-detail-row"><strong>Subtotal:</strong> ' + fp(o.subtotal) + '</div><div class="ord-detail-row"><strong>Ongkir:</strong> ' + fp(o.shipping) + '</div><div class="ord-detail-row"><strong>Total:</strong> ' + fp(o.total) + '</div><div class="ord-detail-row"><strong>Metode Bayar:</strong> ' + payMethodLabel(o) + '</div></div>';
    html += '<div class="ord-detail-section"><h4>Pengiriman</h4><div class="ord-detail-row"><strong>Nama:</strong> ' + o.name + '</div><div class="ord-detail-row"><strong>Telp:</strong> ' + o.phone + '</div><div class="ord-detail-row"><strong>Email:</strong> ' + o.email + '</div><div class="ord-detail-row"><strong>Alamat:</strong> ' + o.address + ', ' + o.city + ' ' + o.zip + '</div></div>';
    document.getElementById('ordBody').innerHTML = html;
    document.getElementById('ordModal').classList.add('show');
}
function closeOrd() { document.getElementById('ordModal').classList.remove('show'); }

// ===== FORM PRODUK =====
function openPF(id) { editId = id || null; pendingImgData = null; pendingImgRemoved = false; document.getElementById('pfImgFile').value = ''; document.getElementById('pfImgErr').textContent = ''; document.getElementById('pfTitle').textContent = id ? 'Edit Produk' : 'Tambah Produk'; if (id) { var p = P.find(function(x) { return x.id === id; }); if (p) { document.getElementById('pfNI').value = p.nm.id; document.getElementById('pfNE').value = p.nm.en; document.getElementById('pfCat').value = p.cat; document.getElementById('pfPr').value = p.pr; document.getElementById('pfSt').value = p.st; document.getElementById('pfRa').value = p.rt; document.getElementById('pfDI').value = p.ds.id; document.getElementById('pfDE').value = p.ds.en; showPfImgPreview(p.customImg || null); } } else { document.getElementById('pfNI').value = ''; document.getElementById('pfNE').value = ''; document.getElementById('pfCat').value = 'amigurumi'; document.getElementById('pfPr').value = ''; document.getElementById('pfSt').value = ''; document.getElementById('pfRa').value = '4.5'; document.getElementById('pfDI').value = ''; document.getElementById('pfDE').value = ''; showPfImgPreview(null); } document.getElementById('pfModal').classList.add('show'); }

function showPfImgPreview(src) {
    var img = document.getElementById('pfImgPreview'), ph = document.getElementById('pfImgPlaceholder'), rmBtn = document.getElementById('pfImgRemoveBtn');
    if (src) { img.src = src; img.style.display = 'block'; ph.style.display = 'none'; rmBtn.style.display = 'inline-flex'; }
    else { img.src = ''; img.style.display = 'none'; ph.style.display = 'flex'; rmBtn.style.display = 'none'; }
}

function handlePfImgUpload(event) {
    var file = event.target.files[0];
    document.getElementById('pfImgErr').textContent = '';
    if (!file) return;
    if (!file.type.match(/^image\//)) { document.getElementById('pfImgErr').textContent = 'File harus berupa gambar'; return; }
    var reader = new FileReader();
    reader.onload = function(e) {
        var img = new Image();
        img.onload = function() {
            var maxDim = 700;
            var w = img.width, h = img.height;
            if (w > h && w > maxDim) { h = Math.round(h * (maxDim / w)); w = maxDim; }
            else if (h > maxDim) { w = Math.round(w * (maxDim / h)); h = maxDim; }
            var canvas = document.createElement('canvas');
            canvas.width = w; canvas.height = h;
            var ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, w, h);
            var dataUrl = canvas.toDataURL('image/jpeg', 0.75);
            pendingImgData = dataUrl;
            pendingImgRemoved = false;
            showPfImgPreview(dataUrl);
        };
        img.onerror = function() { document.getElementById('pfImgErr').textContent = 'Gagal memuat gambar'; };
        img.src = e.target.result;
    };
    reader.onerror = function() { document.getElementById('pfImgErr').textContent = 'Gagal membaca file'; };
    reader.readAsDataURL(file);
}

function removePfImg() {
    pendingImgData = null;
    pendingImgRemoved = true;
    document.getElementById('pfImgFile').value = '';
    showPfImgPreview(null);
}
function closePF() { document.getElementById('pfModal').classList.remove('show'); editId = null; }
function editPF(id) { openPF(id); }
function savePF() { var nmId = document.getElementById('pfNI').value.trim(), nmEn = document.getElementById('pfNE').value.trim(), cat = document.getElementById('pfCat').value, pr = parseInt(document.getElementById('pfPr').value) || 0, st = parseInt(document.getElementById('pfSt').value) || 0, rt = parseFloat(document.getElementById('pfRa').value) || 4.5, dsId = document.getElementById('pfDI').value.trim(), dsEn = document.getElementById('pfDE').value.trim(); if (!nmId || !nmEn || pr <= 0) { toast('Lengkapi data produk!', 'e'); return; } if (editId) { var p = P.find(function(x) { return x.id === editId; }); if (p) { p.nm = {id: nmId, en: nmEn}; p.cat = cat; p.pr = pr; p.st = st; p.rt = Math.min(5, Math.max(0, rt)); p.ds = {id: dsId, en: dsEn}; if (pendingImgData) p.customImg = pendingImgData; else if (pendingImgRemoved) delete p.customImg; toast(t('t_save')); } } else { var newId = P.length > 0 ? Math.max.apply(null, P.map(function(x) { return x.id; })) + 1 : 1; var newP = { id: newId, nm: {id: nmId, en: nmEn}, cat: cat, pr: pr, st: st, rt: Math.min(5, Math.max(0, rt)), ds: {id: dsId, en: dsEn} }; if (pendingImgData) newP.customImg = pendingImgData; P.push(newP); toast(t('t_save')); } for (var i = 0; i < P.length; i++) { P[i].img = P[i].customImg ? P[i].customImg : mkSVG(P[i].cat, P[i].nm.id); } saveProducts(); closePF(); renderProducts(); if (isAdmin) renderAdm(); }
function delPF(id) { if (!confirm('Hapus produk ini?')) return; P = P.filter(function(x) { return x.id !== id; }); saveProducts(); toast(t('t_del')); renderProducts(); if (isAdmin) renderAdm(); }

function exportProductsCode() {
    fetch('script.js').then(function(res) {
        if (!res.ok) throw new Error('fetch-failed');
        return res.text();
    }).then(function(srcText) {
        var startMarker = 'var defaultP = [';
        var startIdx = srcText.indexOf(startMarker);
        var endIdx = srcText.indexOf('\n];', startIdx);
        if (startIdx === -1 || endIdx === -1) throw new Error('marker-not-found');

        var lines = ['var defaultP = ['];
        for (var i = 0; i < P.length; i++) {
            var p = P[i];
            var obj = { id: p.id, nm: p.nm, cat: p.cat, pr: p.pr, ds: p.ds, rt: p.rt, st: p.st };
            if (p.customImg) obj.customImg = p.customImg;
            lines.push('    ' + JSON.stringify(obj) + (i < P.length - 1 ? ',' : ''));
        }
        var newBlock = lines.join('\n');

        var newSrc = srcText.substring(0, startIdx) + newBlock + srcText.substring(endIdx + 1);
        newSrc = newSrc.replace(/var PRODUCTS_VERSION = (\d+);/, function(m, num) {
            return 'var PRODUCTS_VERSION = ' + (parseInt(num, 10) + 1) + ';';
        });

        var blob = new Blob([newSrc], { type: 'text/javascript' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = 'script.js';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        alert('File script.js baru sudah didownload (biasanya masuk folder Downloads)!\n\nLangkah selanjutnya:\n1. Timpa/replace file script.js lama di folder project kamu dengan file yang baru didownload ini\n2. Push/upload ulang script.js itu ke GitHub\n\nSemua produk (termasuk foto) sudah otomatis tertulis di dalamnya — nggak perlu copy-paste manual.');
    }).catch(function(err) {
        alert('Export otomatis gagal.\n\nKemungkinan kamu membuka file ini langsung lewat file:// (bukan lewat Live Server). Pastikan buka website ini lewat Live Server di VS Code, lalu coba klik Export lagi.');
    });
}

